-- HTB deliberate change: TV and safety (package 1 of the 2026-10-19 profile review).
--
-- Approved by Steven on 2026-10-19 (items C3, C4, C10, C11, C12 of the review). Copies these formats
-- from Dictionarry (Dictionarry-Hub/database v2, fb09c84):
--   - C3 guards, -999,999 in every profile: Audio Description, Banned Dual Audio Groups,
--     Banned Language Groups, Banned Groups (Release Title). Upstream's Dual Audio pattern comes with
--     them (it only feeds an unscored HTB format otherwise).
--   - C4 CAM, movies only, -999,999, with one HTB addition: "Not Bluray". Upstream's pattern also
--     matches "TC" (theatrical cut) and "DCP" titles, which hit two real Blu-ray files here.
--   - C10 DVD Quality Tier 1 and 2 replace the retired SD Quality tiers, at the same scores
--     (11,000 and 10,000). They add upstream's "Not Remux" condition. DVD remuxes stay banned.
--   - C11 576p WEB-DL at 70,000, above 480p WEB-DL (60,000), wherever 480p WEB-DL is scored.
--   - C12 ATV (Apple TV, not TV+) gets its own format and pattern, and the Apple TV+ pattern drops
--     "ATV" to match upstream. ATV keeps ATVP's current scores, so nothing scores differently yet.

-- C3: guards.
UPDATE regular_expressions SET pattern = '\bDual[ ._-]?(Audio)?\b|\b(JA|ZH|KO)(?= ?\+ ?.*?\b(EN))|\b(EN)(?= ?\+ ?.*?\b(JA|ZH|KO))\b' WHERE name = 'Dual Audio' AND pattern = '\b((multi[^a-zA-Z]*)|(dual[\s.-](audio|complete)))\b';

-- C4: CAM, movies only, never a Blu-ray source.

-- C10: DVD Quality tiers replace the SD Quality tiers at the same scores.
DELETE FROM custom_formats WHERE name = 'SD Quality Tier 1';
DELETE FROM custom_formats WHERE name = 'SD Quality Tier 2';

-- C11: 576p WEB-DL, just above 480p WEB-DL.

-- C12: ATV as its own format; Apple TV+ no longer matches plain ATV.
UPDATE regular_expressions SET pattern = '\b(ATVP|APTV|Apple TV\+)\s*\b' WHERE name = 'Apple TV+' AND pattern = '\b(ATVP|ATV|APTV|Apple TV\+)\s*\b';
